export type PiktoDirection = "right" | "left" | "down" | "up";

export function getPiktoDirection(desc?: string | null): PiktoDirection {
  if (!desc) return "right";
  try {
    const parsed = JSON.parse(desc);
    if (parsed.direction && ["right", "left", "down", "up"].includes(parsed.direction)) {
      return parsed.direction as PiktoDirection;
    }
  } catch {}
  if (desc === "left" || desc === "right" || desc === "down" || desc === "up") {
    return desc as PiktoDirection;
  }
  return "right";
}

BMA_ICONS_BASE64.ueberspannungsschutz = "data:image/png;base64,";

export function getPiktoIconUrl(type: string, direction: PiktoDirection = "right"): string {
  if (type === "notlicht_pikto_gross") {
    return `/symbols/bma/notlicht_pikto_gross_${direction}.svg`;
  }
  if (type === "notlicht_pikto") {
    return `/symbols/bma/notlicht_pikto_${direction}.svg`;
  }
  if (type === "sirene") {
    return `/symbols/bma/sirene_${direction}.svg`;
  }
  return `/symbols/bma/${type}.svg`;
}

export function getPiktoBase64(type: string, direction: PiktoDirection = "right"): string {
  if (type === "notlicht_pikto_gross") {
    const key = `notlicht_pikto_gross_${direction}`;
    return BMA_ICONS_BASE64[key] || BMA_ICONS_BASE64.notlicht_pikto_gross || BMA_ICONS_BASE64.notlicht_pikto_gross_right;
  }
  if (type === "notlicht_pikto") {
    const key = `notlicht_pikto_${direction}`;
    return BMA_ICONS_BASE64[key] || BMA_ICONS_BASE64.notlicht_pikto || BMA_ICONS_BASE64.notlicht_pikto_right;
  }
  if (type === "sirene") {
    const key = `sirene_${direction}`;
    return BMA_ICONS_BASE64[key] || BMA_ICONS_BASE64.sirene || BMA_ICONS_BASE64.sirene_right;
  }
  return BMA_ICONS_BASE64[type] || BMA_ICONS_BASE64.detector_blue;
}
